import{_ as a,o as t,c as n,ah as s}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"À approuver","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/direction/a-approuver.md","filePath":"src/guide/direction/a-approuver.md"}'),r={name:"guide/direction/a-approuver.md"};function i(o,e,l,u,d,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="a-approuver" tabindex="-1">À approuver <a class="header-anchor" href="#a-approuver" aria-label="Permalink to &quot;À approuver&quot;">​</a></h1><p>La page <strong>À approuver</strong> rassemble tout ce qui attend <strong>votre</strong> décision : dépenses, mobilités d&#39;élèves, mutations du personnel. Elle est faite pour le téléphone : chaque demande tient sur une carte, avec ses boutons. Elle s&#39;ouvre en tête de l&#39;espace <strong>Direction</strong> du menu, ou depuis <strong>Accueil</strong> pour un administrateur.</p><h2 id="ce-que-vous-y-trouvez" tabindex="-1">Ce que vous y trouvez <a class="header-anchor" href="#ce-que-vous-y-trouvez" aria-label="Permalink to &quot;Ce que vous y trouvez&quot;">​</a></h2><p>Seulement ce que vous pouvez décider vous-même :</p><ul><li>une <strong>direction de site</strong> voit les dépenses de ses sites jusqu&#39;au <a href="/era-guide/guide/direction/#depenses">seuil</a>, les mutations qui touchent l&#39;un de ses sites, la part de ses sites dans les mobilités d&#39;élèves, et les <a href="/era-guide/guide/conges.html">congés</a> du personnel de ses sites ;</li><li>la <strong>direction générale</strong> et l&#39;<strong>administrateur</strong> voient tout ;</li><li>le <strong>secrétariat</strong> y voit la part des mobilités d&#39;élèves des sites qui n&#39;ont pas de direction.</li></ul><p>Votre propre demande de congé n&#39;y figure jamais : personne ne décide de la sienne. Une mobilité dont votre part est déjà validée n&#39;y figure plus : elle attend l&#39;autre site. Une dépense au-delà du seuil n&#39;apparaît pas chez la direction de site, puisque la décision revient à la direction générale.</p><h2 id="decider" tabindex="-1">Décider <a class="header-anchor" href="#decider" aria-label="Permalink to &quot;Décider&quot;">​</a></h2><ul><li><strong>Approuver</strong> (ou <strong>Accorder</strong>, pour un congé) tranche la demande en un geste.</li><li><strong>Refuser</strong> demande un motif.</li></ul><p>Dans les deux cas, la personne qui avait fait la demande est prévenue de la décision, avec le motif d&#39;un refus : le caissier pour sa dépense, la personne mutée et celle qui a demandé la mutation, le membre du personnel pour son congé, le parent pour la mobilité de son enfant (par e-mail, une fois la mobilité exécutée ou refusée).</p><ul><li><strong>Détail</strong> ouvre la fiche complète de la demande.</li></ul><p>Une demande décidée quitte la liste aussitôt.</p><h3 id="accueillir-un-eleve" tabindex="-1">Accueillir un élève <a class="header-anchor" href="#accueillir-un-eleve" aria-label="Permalink to &quot;Accueillir un élève&quot;">​</a></h3><p>Pour une mobilité, le site de départ <strong>valide le départ</strong>, le site d&#39;arrivée <strong>valide l&#39;arrivée</strong>. Valider l&#39;arrivée demande de choisir la classe d&#39;accueil : seules les classes du bon département, sur le site d&#39;arrivée et dans l&#39;année en cours, sont proposées, avec leur effectif (par exemple <em>6e A (30/30)</em>).</p><p>Pour placer l&#39;élève dans une classe pleine, cochez <strong>Forcer l&#39;affectation</strong> et donnez le motif. Le dépassement est enregistré et apparaît dans la page <a href="/era-guide/guide/direction/pilotage.html#classes-en-sureffectif">Pilotage</a>.</p><p>Le transfert s&#39;exécute dès que les deux sites ont validé, dans n&#39;importe quel ordre. Si l&#39;élève a des notes dans sa classe actuelle, la fiche de la demande l&#39;indique : elles ne compteront plus après le transfert, comme pour un <a href="/era-guide/guide/secretariat/changements-de-classe.html">changement de classe</a>.</p><h2 id="les-finances-d-un-coup-d-œil" tabindex="-1">Les finances d&#39;un coup d&#39;œil <a class="header-anchor" href="#les-finances-d-un-coup-d-œil" aria-label="Permalink to &quot;Les finances d&#39;un coup d&#39;œil&quot;">​</a></h2><p>En haut de la page, la direction et l&#39;administrateur voient, sur leurs sites et pour l&#39;année choisie dans l&#39;en-tête :</p><ul><li><strong>Encaissé</strong> et <strong>Décaissé</strong> pendant le mois en cours ;</li><li>le <strong>Recouvrement</strong> de l&#39;année, avec le montant restant à encaisser ;</li><li>le total des <strong>Dépenses à décider</strong> qui vous attendent.</li></ul><p>Le lien <strong>Ouvrir le pilotage</strong> mène au détail.</p><h2 id="depuis-une-notification" tabindex="-1">Depuis une notification <a class="header-anchor" href="#depuis-une-notification" aria-label="Permalink to &quot;Depuis une notification&quot;">​</a></h2><p>Activez les notifications dans <strong>Paramètres → Notifications</strong>. Chaque nouvelle demande arrive alors sur votre téléphone ; un appui ouvre la page <strong>À approuver</strong>, avec la demande entourée.</p><p>Si quelqu&#39;un l&#39;a déjà décidée entre-temps, un message le dit, avec un lien <strong>Ouvrir la demande</strong> pour voir ce qui a été décidé.</p>',22)])])}const m=a(r,[["render",i]]);export{g as __pageData,m as default};
